import itertools
import networkx as nx

def solve_accurate_nx(k):
    perms = list(itertools.permutations(range(1, k + 1)))
    G = nx.Graph()
    G.add_nodes_from(range(len(perms)))
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            if all(abs(perms[i][c] - perms[j][c]) <= 1 for c in range(k)):
                G.add_edge(i, j)

    # Find the maximum independent set using the exact algorithm.
    return max_independent_set_exact(G)

def max_independent_set_exact(G):
    nodes = list(G.nodes())
    max_size = 0
    def backtrack(candidates, current_size):
        nonlocal max_size
        if not candidates:
            max_size = max(max_size, current_size)
            return
        if current_size + len(candidates) <= max_size:
            return
        v = candidates[0]
        new_candidates = [c for c in candidates[1:] if not G.has_edge(v, c)]
        backtrack(new_candidates, current_size + 1)
        backtrack(candidates[1:], current_size)
    backtrack(nodes, 0)
    return max_size

print(f"k=4: {solve_accurate_nx(4)}")
